<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';use BAJAMA\Core\Auth;use BAJAMA\Core\License;use BAJAMA\Core\RBAC;use BAJAMA\Core\Tenant;use BAJAMA\Network\MikroTik;use BAJAMA\Network\RouterOsLiveData;Auth::requireLogin();$db=db();License::requireFeature($db,'mikrotik');RBAC::require($db,'mikrotik.view');$org=(int)Tenant::id();$routers=MikroTik::all($db,$org);$routerId=(int)($_GET['router_id']??($routers[0]['id']??0));$rows=[];$error='';try{if($routerId>0)$rows=RouterOsLiveData::read($db,$org,$routerId)['hotspot_active'];}catch(Throwable $e){$error=$e->getMessage();}function ha_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pageTitle='Hotspot Aktif';ob_start();?><meta http-equiv="refresh" content="20"><div class="container-fluid py-4"><h1 class="fw-bold">Hotspot Aktif</h1><p class="text-muted">Sesi hotspot live dari MikroTik. Refresh 20 detik.</p><?php if($error):?><div class="alert alert-danger"><?=ha_h($error)?></div><?php endif;?><form class="mb-3"><select name="router_id" class="form-select" onchange="this.form.submit()"><?php foreach($routers as $r):?><option value="<?=$r['id']?>" <?=$routerId==(int)$r['id']?'selected':''?>><?=ha_h($r['name'])?></option><?php endforeach;?></select></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>User</th><th>Address</th><th>MAC</th><th>Uptime</th><th>Server</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=ha_h($r['user']??$r['name']??'')?></td><td><?=ha_h($r['address']??'')?></td><td><?=ha_h($r['mac-address']??'')?></td><td><?=ha_h($r['uptime']??'')?></td><td><?=ha_h($r['server']??'')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-4">Tidak ada hotspot aktif.</td></tr><?php endif;?></tbody></table></div></div></div><?php $content=ob_get_clean();require __DIR__.'/../app/layout/layout.php';
